const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  const getInfo = (obj) => new Promise((resolve, reject) => obj.evaluate(resolve, reject));
  try {
    // 1. Geometry & Time Definitions
    const dateStart = '2024-01-15';
    const dateEnd = '2024-01-16';
    const delhi = ee.Geometry.Point([77.2090, 28.6139]).buffer(35000).bounds();
    console.log('Date: 2024-01-15; AOI: Delhi (~35 km radius)');

    // 2. Sentinel-2 with s2cloudless
    let s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterDate(dateStart, dateEnd)
      .filterBounds(delhi);
    const s2Count = await getInfo(s2.size());
    console.log(`S2 Images: ${s2Count}`);

    let decided = false;
    if (s2Count > 0) {
      const s2c = ee.ImageCollection('COPERNICUS/S2_CLOUD_PROBABILITY')
        .filterDate(dateStart, dateEnd)
        .filterBounds(delhi);
      const join = ee.Join.saveFirst('cloud_prob');
      const matched = ee.ImageCollection(join.apply(
        s2, s2c, ee.Filter.equals({leftField: 'system:index', rightField: 'system:index'})
      )).filter(ee.Filter.notNull(['cloud_prob']));
      const withCPCount = await getInfo(matched.size());
      console.log(`S2 with CP: ${withCPCount}`);
      if (withCPCount > 0) {
        const cloudCol = matched.map(function(img) {
          const prob = ee.Image(img.get('cloud_prob')).select('probability');
          let cloud = prob.gte(60).rename('cloud');
          const validMask = ee.Image(img).select('B2').mask();
          cloud = cloud.updateMask(validMask);
          return cloud;
        });
        const cloudImg = ee.ImageCollection(cloudCol).max().rename('cloud');
        const stats = await getInfo(cloudImg.reduceRegion({
          reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
          geometry: delhi, scale: 1000, maxPixels: 1e13, tileScale: 4
        }));
        const mean = stats ? stats.cloud_mean : null;
        const count = stats ? stats.cloud_count : null;
        if (count === null || mean === null || isNaN(mean)) {
          console.log('Calculation invalid (null/NaN).');
          console.log('C3');
          return;
        }
        console.log(`Valid km-pixels: ${count}`);
        if (count === 0) {
          console.log('No valid pixels after masking.');
          console.log('C2');
          return;
        }
        console.log(`Cloud fraction: ${mean.toFixed(3)}`);
        console.log(`Cloud %: ${(mean * 100).toFixed(1)}`);
        console.log(mean >= 0.99 ? 'A' : 'B');
        return;
      }
      // If S2 exists but no cloud-probability match, fall through to MODIS fallback
    }

    // 3. Fallback: MODIS Terra/Aqua daily cloud state
    const modTerra = ee.ImageCollection('MODIS/006/MOD09GA').filterDate(dateStart, dateEnd).filterBounds(delhi);
    const modAqua = ee.ImageCollection('MODIS/006/MYD09GA').filterDate(dateStart, dateEnd).filterBounds(delhi);
    const tCount = await getInfo(modTerra.size());
    const aCount = await getInfo(modAqua.size());
    console.log(`MODIS Terra: ${tCount}, Aqua: ${aCount}`);
    if ((tCount || 0) === 0 && (aCount || 0) === 0) {
      console.log('No imagery available for the date/AOI.');
      console.log('C1');
      return;
    }
    const modCloud = function(img) {
      const qa = img.select('state_1km');
      const cloudState = qa.bitwiseAnd(3); // bits 0-1: 0=clear,1=cloud,2=mixed,3=not set
      const isCloudOrMixed = cloudState.eq(1).or(cloudState.eq(2));
      const cloudShadow = qa.rightShift(2).bitwiseAnd(1).eq(1); // bit 2: cloud shadow
      const cloud = isCloudOrMixed.or(cloudShadow).rename('cloud');
      const valid = img.select('sur_refl_b01').mask(); // use reflectance mask
      return cloud.updateMask(valid);
    };
    const imgList = [];
    if (tCount > 0) imgList.push(modCloud(modTerra.mosaic()));
    if (aCount > 0) imgList.push(modCloud(modAqua.mosaic()));
    const combinedCloud = ee.ImageCollection(imgList).min().rename('cloud'); // AND across Terra/Aqua
    const mStats = await getInfo(combinedCloud.reduceRegion({
      reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
      geometry: delhi, scale: 1000, maxPixels: 1e13, tileScale: 4
    }));
    const mMean = mStats ? mStats.cloud_mean : null;
    const mCount = mStats ? mStats.cloud_count : null;
    if (mCount === null || mMean === null || isNaN(mMean)) {
      console.log('Calculation invalid (null/NaN).');
      console.log('C3');
      return;
    }
    console.log(`Valid km-pixels: ${mCount}`);
    if (mCount === 0) {
      console.log('No valid pixels after masking.');
      console.log('C2');
      return;
    }
    console.log(`Cloud fraction: ${mMean.toFixed(3)}`);
    console.log(`Cloud %: ${(mMean * 100).toFixed(1)}`);
    console.log(mMean >= 0.99 ? 'A' : 'B');
  } catch (e) {
    console.log(`Error: ${e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
